/**
 * Sumber tunggal warna status Data Pengajuan.
 * DISAMAKAN PERSIS dengan Document States (meta.states) doctype "Data Pengajuan"
 * — itulah warna yang dipakai indikator Frappe (form & list) untuk status ini.
 * Dipakai konsisten di list view (titik) & detail view (pill).
 */

// status → nama warna Frappe (persis dari Document States doctype).
const STATE_COLOR = {
	Draft: 'gray',
	Submitted: 'blue',
	'Proses CA': 'orange',
	'Proses CA 1': 'orange',
	'CA Approved': 'green',
	'CA Rejected': 'red',
	'Approval Perubahan Data': 'yellow',
	'Approval Perubahan Data BA': 'yellow',
	'Approval Perubahan Data BR': 'yellow',
	// Tidak ada di Document States doctype → samakan dgn varian sibling (Yellow).
	'Approval Perubahan Data CAA': 'yellow',
	'Proses Banding': 'pink',
	'Banding Approved': 'light-blue',
	'Banding Rejected': 'purple',
	Cancel: 'red',
	'Cancel Approval': 'red',
	'Request Rekom Banding': 'red',
	'Sudah Pencairan': 'green',
	// Tidak ada di Document States doctype → guess_colour Frappe ("Rejected" → merah).
	'Rejected Final': 'red',
}

// Daftar status untuk picker filter (urut sesuai alur kredit). Sumber tunggal
// supaya selaras dengan warna di STATE_COLOR. Dipakai bottom-sheet filter
// Data Pengajuan (pilih banyak → operator Frappe `in`).
export const STATUS_OPTIONS = Object.keys(STATE_COLOR)

// Tebak warna untuk status tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	if (/Pending|Review|Medium|Not Approved/i.test(s)) return 'orange'
	if (/Open|Urgent|High|Failed|Rejected|Error/i.test(s)) return 'red'
	if (
		/Closed|Finished|Converted|Completed|Complete|Confirmed|Approved|Yes|Active|Available|Paid|Success/i.test(
			s
		)
	)
		return 'green'
	if (/Submitted/i.test(s)) return 'blue'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk header detail & badge.
