import { currentUser, loadMyRoles } from './user'

// Role portal yang dibatasi hanya cabang sendiri.
const ROLES_CABANG_ONLY = ['Pimcab']

// Apakah user aktif termasuk role yang dibatasi per-cabang?
// Admin / System Manager TIDAK PERNAH dibatasi (lihat semua cabang) — meski di
// site ini Administrator kerap memegang semua role (termasuk Pimcab), supaya
// list tidak ikut tersaring habis jadi "cabang = __NO_CABANG__".
export function isCabangRestricted(roles) {
	const r = roles || currentUser.roles || []
	if (currentUser.user === 'Administrator' || r.includes('System Manager')) return false
	return ROLES_CABANG_ONLY.some((role) => r.includes(role))
}

// Tunggu roles selesai di-fetch (maks `timeout` ms) supaya keputusan "dibatasi /
// tidak" tidak salah saat halaman dibuka langsung via URL (hard refresh).
function waitRolesLoaded(timeout = 3000) {
	if (currentUser.rolesLoaded) return Promise.resolve()
	loadMyRoles()
	return new Promise((resolve) => {
		const start = Date.now()
		const iv = setInterval(() => {
			if (currentUser.rolesLoaded || Date.now() - start > timeout) {
				clearInterval(iv)
				resolve()
			}
		}, 50)
	})
}

// Ambil cabang user aktif dari doctype "User Juragan".
// Di-cache sekali per sesi. Tanpa menyentuh app backend juragan.
//
// PENTING: pakai frappe.client.GET (bukan get_value). has_permission controller
// User Juragan hanya mengizinkan baca record SENDIRI; get_value melakukan precheck
// izin doctype-level (doc=None) → selalu 403 untuk role non-admin. frappe.client.get
// mengecek izin DENGAN dokumennya → record sendiri lolos. name = user_id (autoname
// "field:user_id"), jadi name == email user aktif.
let _cabangCache
export async function fetchUserCabang() {
	if (_cabangCache !== undefined) return _cabangCache
	const user = currentUser.user
	if (!user) return (_cabangCache = null)
	try {
		const params = new URLSearchParams({ doctype: 'User Juragan', name: user })
		const res = await fetch(`/api/method/frappe.client.get?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			cache: 'no-store', // jangan pakai cache HTTP → cabang selalu fresh
			headers: { Accept: 'application/json' },
		})
		const doc = (await res.json())?.message
		_cabangCache = (doc && doc.cabang) || null
	} catch (e) {
		_cabangCache = null
	}
	return _cabangCache
}

// Bentuk satu filter [field, op, value] untuk membatasi list ke cabang user:
//  - "SP" = cabang induk multi (SP, SP1..SP4) → pakai LIKE (meniru logika desk).
//    (Catatan: kombinasi khusus "OR cabang = 'DM'" di backend TIDAK direplikasi
//     di sini karena filter frontend hanya satu kondisi AND.)
//  - cabang kosong / tak ketemu → FAIL-CLOSED: filter yang tak match apa pun,
//    supaya user yang dibatasi tidak malah melihat SEMUA data.
//  - selain itu → cabang = nilai (sama persis).
//
// `field` = nama kolom cabang di doctype tujuan. Default `cabang`, TAPI tidak
// semua doctype memakai nama itu untuk cabang operasionalnya: di Master Data
// Nasabah kolom `cabang` hanya berisi cabang induk (SP/OD/TP) sedangkan cabang
// sebenarnya ada di `cabang_jss` (SP1/SP2/SP3/TP1/DM/OD) — yang juga dipakai
// backend di get_permission_query_conditions. Salah kolom = list kosong total.
export function cabangFilter(cab, field = 'cabang') {
	if (!cab) return [field, '=', '__NO_CABANG__']
	if (cab === 'SP') return [field, 'like', '%SP%']
	return [field, '=', cab]
}

// Resolusi lengkap: kembalikan filter cabang yang harus dipasang di list, atau
// null kalau user TIDAK dibatasi. Panggil sekali sebelum fetch pertama.
export async function resolveCabangFilter(field = 'cabang') {
	await waitRolesLoaded()
	if (!isCabangRestricted()) return null
	const cab = await fetchUserCabang()
	return cabangFilter(cab, field)
}
